<script>
document.addEventListener('DOMContentLoaded',()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const reveals=[...document.querySelectorAll('[data-reveal]')];if(reduced)reveals.forEach(el=>el.classList.add('visible'));else{const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});reveals.forEach((el,i)=>{el.style.transitionDelay=`${(i%3)*80}ms`;revealObserver.observe(el)})}const progress=document.querySelector('.pl-progress'),product=document.querySelector('[data-product]'),stage=document.querySelector('[data-stage]');let mx=0,my=0,tx=0,ty=0,raf=0;function render(){tx+=(mx-tx)*.07;ty+=(my-ty)*.07;if(product&&!reduced){const scroll=Math.min(scrollY/innerHeight,1);product.style.transform=`rotateX(${5-ty*5+scroll*3}deg) rotateY(${-9+tx*8+scroll*7}deg) rotateZ(${1-scroll}deg) translateY(${scroll*22}px)`}raf=requestAnimationFrame(render)}if(!reduced)render();stage?.addEventListener('pointermove',e=>{const r=stage.getBoundingClientRect();mx=(e.clientX-r.left)/r.width-.5;my=(e.clientY-r.top)/r.height-.5});stage?.addEventListener('pointerleave',()=>{mx=0;my=0});addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max?scrollY/max:0})`},{passive:true});const steps=[...document.querySelectorAll('.pl-step')],scenes=[...document.querySelectorAll('.pl-scene')];const storyObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){const index=+entry.target.dataset.step;steps.forEach((step,i)=>step.classList.toggle('active',i===index))}}),{rootMargin:'-35% 0px -45%'});scenes.forEach(scene=>storyObserver.observe(scene));const counters=[...document.querySelectorAll('[data-count]')];const countObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target,target=+el.dataset.count,start=performance.now();function tick(now){const p=Math.min((now-start)/1200,1);el.textContent=Math.round(target*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick);countObserver.unobserve(el)}));counters.forEach(el=>countObserver.observe(el));addEventListener('pagehide',()=>cancelAnimationFrame(raf))});
</script>
